class Auto(object):
    """The ``Auto`` specifier type enables automatic target resolution in glom.

    When encountered, ``Auto`` will be replaced by the current target value,
    allowing for dynamic specification construction based on the data being
    processed. This is useful for streaming operations and variable capture.

    >>> target = {'a': 1}
    >>> glom(target, Auto)
    {'a': 1}
    """
    def __repr__(self):
        return 'Auto'


class Fill(object):
    """The ``Fill`` specifier type allows filling in missing values during
    data transformation.

    When a path doesn't exist in the target, ``Fill`` provides a default
    value to use instead of raising an error. This enables robust data
    extraction from partially populated structures.

    Args:
       spec: The specification to use for extracting data
       default: A default value to use when the spec fails

    >>> target = {'a': 1}
    >>> glom(target, Fill('b', default=0))
    0
    """
    def __init__(self, spec, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            return scope[glom](target, self.spec, scope)
        except Exception:
            return self.default

    def __repr__(self):
        cn = self.__class__.__name__
        if self.default is not None:
            return '%s(%r, default=%r)' % (cn, self.spec, self.default)
        return '%s(%r)' % (cn, self.spec)


class Iter(object):
    """The ``Iter`` specifier type enables iteration over targets.

    ``Iter`` wraps a sub-spec and applies it to each element of an iterable
    target, returning a list of results. This is useful for applying
    transformations across collections.

    Args:
       subspec: The specification to apply to each element

    >>> target = [1, 2, 3]
    >>> glom(target, Iter(T * 2))
    [2, 4, 6]
    """
    def __init__(self, subspec=None):
        self.subspec = subspec

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        iterator = iterate(target)
        ret = []
        for i, item in enumerate(iterator):
            child_scope = scope.new_child({Path: scope[Path] + [i]})
            if self.subspec is None:
                val = item
            else:
                val = scope[glom](item, self.subspec, child_scope)
            if val is not SKIP:
                ret.append(val)
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        if self.subspec is None:
            return '%s()' % (cn,)
        return '%s(%r)' % (cn, self.subspec)


class Let(object):
    """The ``Let`` specifier type allows binding intermediate values during
    data transformation.

    ``Let`` creates named bindings that can be referenced by subsequent
    specifications. This enables more complex data transformations where
    intermediate results need to be reused.

    Args:
       mappings: A dictionary mapping names to specifications

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'c': ('a', lambda x: x * 2)}, T['c'] + T['b']))
    4
    """
    def __init__(self, mappings, spec=None):
        if not isinstance(mappings, dict):
            raise TypeError('Let expected a dict of mappings, not: %r' % (mappings,))
        self.mappings = mappings
        self.spec = spec

    def glomit(self, target, scope):
        child_scope = scope.copy()
        local_vars = {}
        for name, subspec in self.mappings.items():
            local_vars[name] = scope[glom](target, subspec, scope)
        child_scope.update(local_vars)
        if self.spec is None:
            return local_vars
        return scope[glom](target, self.spec, child_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.spec is None:
            return '%s(%r)' % (cn, self.mappings)
        return '%s(%r, %r)' % (cn, self.mappings, self.spec)


class Invoke(object):
    """The ``Invoke`` specifier type allows calling functions with glom specs.

    ``Invoke`` takes a function and a list of arguments (which can be specs),
    evaluates those specs against the target, and calls the function with
    the resulting values.

    Args:
       func: A callable to invoke
       args: Positional arguments (can be specs or literals)
       kwargs: Keyword arguments (can be specs or literals)

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Invoke(sum, ['a', 'b']))
    3
    """
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        resolved_args = []
        for arg in self.args:
            if type(arg) is Spec:
                resolved_args.append(scope[glom](target, arg, scope))
            else:
                resolved_args.append(arg)
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            if type(v) is Spec:
                resolved_kwargs[k] = scope[glom](target, v, scope)
            else:
                resolved_kwargs[k] = v
        return self.func(*resolved_args, **resolved_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        args_repr = ', '.join([repr(a) for a in self.args])
        kwargs_repr = ', '.join(['%s=%r' % (k, v) for k, v in self.kwargs.items()])
        parts = [repr(self.func), args_repr, kwargs_repr]
        parts = [p for p in parts if p]
        return '%s(%s)' % (cn, ', '.join(parts))


